util functions: https://github.com/daman1807/iptables/blob/main/util.go 
```
func (buf *LineBuffer) Write(args ...interface{}) {
	for i, arg := range args {
		if i > 0 {
			buf.b.WriteByte(' ')
		}
		switch x := arg.(type) {
		case string:
			buf.b.WriteString(x)
		case []string:
			for j, s := range x {
				if j > 0 {
					buf.b.WriteByte(' ')
				}
				buf.b.WriteString(s)
			}
		case []byte:
			buf.b.Write(x)
		default:
			panic(fmt.Sprintf("unknown argument type: %T", x))
		}
	}
	buf.b.WriteByte('\n')
	buf.lines++
}

func (buf *LineBuffer) NewWrite(strArrays ...[]string) {
	for i, strArray := range strArrays {
		if i > 0 {
			buf.b.WriteByte(' ')
		}
		for j, str := range strArray {
			if j > 0 {
				buf.b.WriteByte(' ')
			}
			buf.b.WriteString(str)

		}
	}
	buf.b.WriteByte('\n')
	buf.lines++
}
